"use client";

import history from "@/lib/research/history.json";

interface Stat {
  n: number;
  winRate: number | null;
  ci95: [number, number] | (number | null)[] | null;
  net?: number;
  coverage?: number;
  signals?: number;
}

const pct = (x: number | null | undefined, d = 1) => (x === null || x === undefined ? "—" : `${(x * 100).toFixed(d)}%`);

/**
 * Verified historical results, generated by scripts/research/export_history.py from
 * the research outputs. Shown so the user sees tested numbers, not promises.
 */
export function HistoryPanel() {
  const be = 1 / (1 + history.payout);
  const rows = history.versions as { id: string; label: string; test: Stat; late: Stat | null }[];
  return (
    <section className="glass-quiet p-4 text-sm" data-testid="history-panel">
      <h3 className="font-semibold">Asli data par tested nataij</h3>
      <p className="mt-1 text-xs text-muted">
        Test period {history.period.test} (training mein shamil nahin) · {history.testOpportunities.toLocaleString()} moqay · 6 pairs · {pct(history.payout, 0)} payout par barabar ke liye {pct(be)} chahiye.
      </p>
      <div className="mt-2 overflow-x-auto">
        <table className="w-full text-left text-xs">
          <thead className="text-muted">
            <tr>
              <th className="py-1 font-normal">Version</th>
              <th className="font-normal">Trades</th>
              <th className="font-normal">Jeet (95%)</th>
              <th className="font-normal">Der se</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((r) => (
              <tr key={r.id} className="border-t border-white/5 align-top">
                <td className="py-1.5 pr-2">{r.label}</td>
                <td>{r.test.n.toLocaleString()}</td>
                <td className={r.test.ci95 && (r.test.ci95[0] ?? 0) > be ? "text-call" : (r.test.winRate ?? 0) < be ? "text-put" : ""}>
                  {pct(r.test.winRate)}
                  {r.test.ci95 && r.test.ci95[0] !== null ? ` (${pct(r.test.ci95[0] as number, 0)}–${pct(r.test.ci95[1] as number, 0)})` : ""}
                </td>
                <td className={r.late && (r.late.winRate ?? 0) < be ? "text-put" : ""}>{r.late ? pct(r.late.winRate) : "—"}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <details className="mt-2">
        <summary className="cursor-pointer text-xs text-cyan">Pair, session aur regime ke hisaab se (v2)</summary>
        <ul className="mt-1 space-y-0.5 text-xs text-muted">
          {Object.entries(history.v2ByPair as Record<string, Stat>).map(([k, v]) => (
            <li key={k}>
              {k.replace("_", "/")}: {pct(v.winRate)} ({v.n})
            </li>
          ))}
          {Object.entries(history.v2BySession as Record<string, Stat>).map(([k, v]) => (
            <li key={k}>
              {k}: {pct(v.winRate)} ({v.n})
            </li>
          ))}
          {Object.entries(history.v2ByRegime as Record<string, Stat>).map(([k, v]) => (
            <li key={k}>
              Regime {k}: {pct(v.winRate)} ({v.n})
            </li>
          ))}
        </ul>
      </details>
      <p className="mt-2 text-xs text-faint">
        OTC: test nahin ho sakta — kisi jaiz source se OTC data mojood nahin. 90% kahin nahin mila; validation par sab se ooncha {pct(history.highestValidationBucket.winRate)} sirf {history.highestValidationBucket.n} trades par tha. Purane nataij mustaqbil ki zamanat nahin.
      </p>
    </section>
  );
}
